with enriched as (select e.*, o.discount, o.channel from shipments e left join orders o on e.order_id = o.id) select s.id, s.order_id, s.shipped_date, s.delivered_date, s.cost, s.status, s.discount, s.channel, case when channel rlike '^(mobile|store)$' then 'CORE' else 'GROUP_B' end as channel_zone, (select min(t2.cost) from shipments t2 where t2.order_id = s.order_id) as min_shipment_cost from enriched s;
